def qnow():
    s=state()
    return np.array([s[n] for n in spec['kinematics']['joint_names']])

def rownow():
    s=state()
    return np.array([0.,0.,0.]+[s[f'torso_joint{i}'] for i in range(1,5)]+[s[f'left_arm_joint{i}'] for i in range(1,8)]+[0.07,0.07]+[s[f'right_arm_joint{i}'] for i in range(1,8)]+[0.07,0.07])

def drive(x=0.,y=0.,yaw=0.,steps=60):
    a=rownow()
    a[:3]=np.array([x,y,yaw])/steps
    rows=np.tile(a,(steps+10,1))
    rows[-10:,:3]=0
    return keep(r.submit('joint_position',rows,dt=1/30,depth=True,video='both',video_fps=5))

def pixel(cam,u,v):
    z=float(obs.last_depth[cam][round(v),round(u)])
    cal=obs.meta['cameras'][cam]
    K=np.array(cal['intrinsic_cv'])
    E=np.array(cal['extrinsic_cv'])
    pc=np.linalg.inv(K)@np.array([u,v,1])*z
    return E[:,:3].T@(pc-E[:,3])

def moveq(q,seconds=2.,grip=(0.07,0.07)):
    start=rownow(); end=start.copy()
    end[3:14]=q[:11];end[16:23]=q[11:]
    end[14:16]=grip[0];end[23:25]=grip[1]
    n=round(seconds*30)
    rows=np.linspace(start,end,n)
    rows[:,14:16]=grip[0];rows[:,23:25]=grip[1]
    rows=np.vstack([rows,np.tile(end,(15,1))])
    return keep(r.submit('joint_position',rows,dt=1/30,depth=True,video='both',video_fps=5))

def target(frame,pose):
    sol=r.ik({frame:pose},seed=qnow(),base_pose=obs.group('base_pose',now=True))
    print('IK',sol,flush=True)
    return sol
